# file: domain_adapt_dann_mmd.py
import torch, torch.nn as nn, torch.optim as optim
import numpy as np
from sklearn.cluster import KMeans
from sklearn.metrics.pairwise import rbf_kernel
from torch.utils.data import DataLoader, TensorDataset
# 梯度反转层实现，用于对抗训练
class GradReverse(torch.autograd.Function):
@staticmethod
def forward(ctx, x, lamb):
ctx.lamb = lamb
return x.view_as(x)
@staticmethod
def backward(ctx, grad):
return grad.neg() * ctx.lamb, None
# 简化的域适应网络：特征提取、分类器、域判别器
class DomainAdapNet(nn.Module):
def __init__(self, feat_dim=512, nclass=10):
super().__init__()
self.feature = nn.Sequential(
nn.Conv2d(3,32,3,padding=1), nn.ReLU(), nn.MaxPool2d(2),
nn.Conv2d(32,64,3,padding=1), nn.ReLU(), nn.MaxPool2d(2),
nn.Flatten(), nn.Linear(64*56*56, feat_dim), nn.ReLU()
)
self.classifier = nn.Linear(feat_dim, nclass)
self.domain = nn.Sequential(nn.Linear(feat_dim, 100), nn.ReLU(), nn.Linear(100,2))
def forward(self, x, lamb=0.0):
f = self.feature(x)
if lamb>0:
rev = GradReverse.apply(f, lamb)
dlogits = self.domain(rev)
else:
dlogits = self.domain(f*0.0) # 占位
return self.classifier(f), dlogits, f
# 基于RBF 的MMD 近似
def mmd_rbf(X, Y, gamma=1.0):
XX = rbf_kernel(X, X, gamma)
YY = rbf_kernel(Y, Y, gamma)
XY = rbf_kernel(X, Y, gamma)
return XX.mean() + YY.mean() - 2*XY.mean()
